import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] items = {1, 2, 3};
        Deque<Integer> stack = new ArrayDeque<>();   // used as a stack: push / pop
        Queue<Integer> queue = new ArrayDeque<>();   // used as a queue: offer / poll
        String in = "";
        for (int x : items) {
            in += " " + x;
            stack.push(x);     // goes on top
            queue.offer(x);    // goes to the back
        }
        System.out.println("Input order:" + in);

        String out = "";
        while (!stack.isEmpty()) out += " " + stack.pop();    // newest leaves first
        System.out.println("Stack removes (LIFO):" + out);

        out = "";
        while (!queue.isEmpty()) out += " " + queue.poll();   // oldest leaves first
        System.out.println("Queue removes (FIFO):" + out);
        // Time: O(1) per add/remove. Space: O(N).
    }
}

