    queue<int> q;     // push at the back, pop at the front
    cout << "Input order:";
    for (int x : items) {
        cout << " " << x;
        st.push(x);   // goes on top
        q.push(x);    // goes to the back
    }
    cout << "\n";

    cout << "Stack removes (LIFO):";
    while (!st.empty()) { cout << " " << st.top(); st.pop(); }   // newest leaves first
    cout << "\n";

    cout << "Queue removes (FIFO):";
    while (!q.empty()) { cout << " " << q.front(); q.pop(); }    // oldest leaves first
    cout << "\n";
    // Time: O(1) per add/remove. Space: O(N).
    return 0;
}

