public class Main {
    static int[] buf = new int[4];   // fixed array, used as a ring
    static int head = 0, size = 0;   // head = index of the oldest item

    static void offer(int x) {
        if (size == buf.length) grow();          // full: make a bigger array first
        buf[(head + size) % buf.length] = x;     // % makes the tail wrap around to slot 0
        size++;
    }

    static int poll() {
        int x = buf[head];
        head = (head + 1) % buf.length;          // no shifting: just move head forward
        size--;
        return x;
    }

    static void grow() {                         // copy items in queue order into 2x array
        int[] bigger = new int[buf.length * 2];
        for (int i = 0; i < size; i++) bigger[i] = buf[(head + i) % buf.length];
        buf = bigger;
        head = 0;
    }

    public static void main(String[] args) {
        for (int x = 1; x <= 4; x++) offer(x);
        System.out.println("Capacity 4, offer 1 2 3 4");
        int a = poll(), b = poll();
        System.out.println("poll twice: " + a + " " + b);
        offer(5); offer(6);
        System.out.println("offer 5 6: tail wraps to slots 0 and 1, capacity still " + buf.length);
        offer(7);
        System.out.println("offer 7: array was full, capacity grows to " + buf.length);
        String out = "";
        while (size > 0) out += " " + poll();
        System.out.println("poll the rest:" + out);
        // Time: O(1) amortized per offer/poll (a grow costs O(N) but is rare). Space: O(N).
    }
}

