using System;

class Program {
    static int[] buf = new int[4];   // fixed array, used as a ring
    static int head = 0, size = 0;   // head = index of the oldest item

    static void Grow() {             // copy items in queue order into a 2x array
        int[] bigger = new int[buf.Length * 2];
        for (int i = 0; i < size; i++) bigger[i] = buf[(head + i) % buf.Length];
        buf = bigger;
        head = 0;
    }

    static void Offer(int x) {
        if (size == buf.Length) Grow();          // full: make a bigger array first
        buf[(head + size) % buf.Length] = x;     // % makes the tail wrap around to slot 0
        size++;
    }

    static int Poll() {
        int x = buf[head];
        head = (head + 1) % buf.Length;          // no shifting: just move head forward
        size--;
        return x;
    }

    static void Main() {
        for (int x = 1; x <= 4; x++) Offer(x);
        Console.WriteLine("Capacity 4, offer 1 2 3 4");
        int a = Poll(), b = Poll();
        Console.WriteLine("poll twice: " + a + " " + b);
        Offer(5); Offer(6);
        Console.WriteLine("offer 5 6: tail wraps to slots 0 and 1, capacity still " + buf.Length);
        Offer(7);
        Console.WriteLine("offer 7: array was full, capacity grows to " + buf.Length);
        string result = "";
        while (size > 0) result += " " + Poll();
        Console.WriteLine("poll the rest:" + result);
        // Time: O(1) amortized per offer/poll (a grow costs O(N) but is rare). Space: O(N).
    }
}

