import java.util.*;

public class Main {
    static String check(String s) {
        String opens = "([{", closes = ")]}";
        Deque<Character> st = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            int k = closes.indexOf(c);            // -1 means c is an opener
            if (k < 0) { st.push(c); continue; }  // opener: wait on the stack
            if (st.isEmpty()) return "invalid: closer with nothing open";
            if (st.pop() != opens.charAt(k)) return "invalid: wrong type or order";
        }
        // anything still waiting was never closed
        return st.isEmpty() ? "valid" : "invalid: opener never closed";
    }

    public static void main(String[] args) {
        String[] tests = {"([]{})", ")(", "(]", "([)]", "(("};
        for (String t : tests) System.out.println(t + " -> " + check(t));
        // Time: O(N). Space: O(N) for the stack.
    }
}

