#include <bits/stdc++.h>
using namespace std;

string check(const string& s) {
    string opens = "([{", closes = ")]}";
    vector<char> st;
    for (char c : s) {
        size_t k = closes.find(c);                          // npos means c is an opener
        if (k == string::npos) { st.push_back(c); continue; }   // opener: wait on the stack
        if (st.empty()) return "invalid: closer with nothing open";
        char top = st.back(); st.pop_back();
        if (top != opens[k]) return "invalid: wrong type or order";
    }
    // anything still waiting was never closed
    return st.empty() ? "valid" : "invalid: opener never closed";
}

int main() {
    vector<string> tests = {"([]{})", ")(", "(]", "([)]", "(("};
    for (const string& t : tests) cout << t << " -> " << check(t) << "\n";
    // Time: O(N). Space: O(N) for the stack.
    return 0;
}

