import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] ops = {5, 3, 7, 3, 0, 0, 0};          // a number = push it, 0 = pop
        Deque<int[]> st = new ArrayDeque<>();        // each entry is {value, minSoFar}
        for (int x : ops) {
            if (x != 0) {
                // the min at this height = smaller of x and the min just below
                int min = st.isEmpty() ? x : Math.min(x, st.peek()[1]);
                st.push(new int[]{x, min});
                System.out.println("push " + x + " -> min " + st.peek()[1]);
            } else {
                int[] top = st.pop();                // pop needs no repair work:
                String min = st.isEmpty() ? "none" : "" + st.peek()[1];  // entry below knows its own min
                System.out.println("pop " + top[0] + " -> min " + min);
            }
        }
        // Time: O(1) for push, pop and getMin. Space: O(N), two numbers per element.
    }
}

