import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] a = {2, 1, 5, 3, 6, 4};
        int n = a.length, pushes = 0, pops = 0;
        int[] res = new int[n];
        Arrays.fill(res, -1);                       // -1 = no greater value to the right
        Deque<Integer> st = new ArrayDeque<>();     // indices still waiting for an answer
        for (int i = 0; i < n; i++) {
            // a[i] is the answer for every smaller value waiting on the stack
            while (!st.isEmpty() && a[st.peek()] < a[i]) { res[st.pop()] = a[i]; pops++; }
            st.push(i);                             // each index is pushed exactly once
            pushes++;
        }
        String in = "", out = "";
        for (int i = 0; i < n; i++) { in += " " + a[i]; out += " " + res[i]; }
        System.out.println("Input:" + in);
        System.out.println("Next greater:" + out);
        System.out.println("Pushes: " + pushes + ", pops: " + pops
            + ", total " + (pushes + pops) + " <= 2N = " + (2 * n));
        // Time: O(N) because pops can never exceed pushes. Space: O(N).
    }
}

