import java.util.*;

public class Main {
    // mode 0 = next greater, 1 = next smaller, 2 = previous greater, 3 = previous smaller
    static int[] solve(int[] a, int mode) {
        int n = a.length;
        int[] res = new int[n];
        Arrays.fill(res, -1);
        Deque<Integer> st = new ArrayDeque<>();        // indices
        for (int i = 0; i < n; i++) {
            while (!st.isEmpty() && shouldPop(a[st.peek()], a[i], mode)) {
                int j = st.pop();
                if (mode < 2) res[j] = a[i];           // "next": the popped one gets its answer
            }
            if (mode >= 2 && !st.isEmpty()) res[i] = a[st.peek()];  // "previous": the survivor is the answer
            st.push(i);
        }
        return res;
    }

    // the only line that differs between the four variants
    static boolean shouldPop(int top, int x, int mode) {
        if (mode == 0) return top < x;
        if (mode == 1) return top > x;
        if (mode == 2) return top <= x;
        return top >= x;
    }

    static String fmt(int[] v) { String s = ""; for (int x : v) s += " " + x; return s; }

    public static void main(String[] args) {
        int[] a = {4, 2, 6, 2, 5};
        String[] names = {"Next greater:", "Next smaller:", "Previous greater:", "Previous smaller:"};
        System.out.println("Input:" + fmt(a));
        for (int m = 0; m < 4; m++) System.out.println(names[m] + fmt(solve(a, m)));
        // Time: O(N) per variant. Space: O(N).
    }
}

