# the only line that differs between the four variants
def should_pop(top, x, mode):
    if mode == 0:
        return top < x
    if mode == 1:
        return top > x
    if mode == 2:
        return top <= x
    return top >= x

# mode 0 = next greater, 1 = next smaller, 2 = previous greater, 3 = previous smaller
def solve(a, mode):
    res = [-1] * len(a)
    st = []                                   # indices
    for i, x in enumerate(a):
        while st and should_pop(a[st[-1]], x, mode):
            j = st.pop()
            if mode < 2:
                res[j] = x                    # "next": the popped one gets its answer
        if mode >= 2 and st:
            res[i] = a[st[-1]]                # "previous": the survivor is the answer
        st.append(i)
    return res

def fmt(v):
    return "".join(" " + str(x) for x in v)

a = [4, 2, 6, 2, 5]
names = ["Next greater:", "Next smaller:", "Previous greater:", "Previous smaller:"]
print("Input:" + fmt(a))
for m in range(4):
    print(names[m] + fmt(solve(a, m)))
# Time: O(N) per variant. Space: O(N).

