import java.util.*;

public class Main {
    static long largest(int[] h) {
        int n = h.length;
        long best = 0;
        Deque<Integer> st = new ArrayDeque<>();        // indices, heights increasing
        for (int i = 0; i <= n; i++) {
            int cur = (i == n) ? 0 : h[i];             // sentinel bar of height 0 flushes the stack
            while (!st.isEmpty() && cur <= h[st.peek()]) {
                int height = h[st.pop()];              // this bar is the shortest in its rectangle
                int left = st.isEmpty() ? -1 : st.peek();   // nearest smaller bar on the left
                long area = (long) height * (i - left - 1); // i is the nearest smaller on the right
                best = Math.max(best, area);
            }
            st.push(i);
        }
        return best;
    }

    static String fmt(int[] v) { String s = ""; for (int x : v) s += " " + x; return s; }

