        int[][] tests = {{2, 1, 5, 6, 2, 3}, {3, 3, 3}, {1, 2, 3, 4}};
        for (int[] h : tests)
            System.out.println("Heights:" + fmt(h) + " -> largest area " + largest(h));
        // Time: O(N), each bar is pushed and popped once. Space: O(N).
    }
}

