import java.util.*;

public class Main {
    static Deque<Integer> in = new ArrayDeque<>(), out = new ArrayDeque<>();
    static int stackOps = 0;                       // every stack push or pop counts as 1

    static void push(int x) { in.push(x); stackOps++; }

    static int pop() {
        if (out.isEmpty()) {                       // refill ONLY when out is empty
            while (!in.isEmpty()) {                // moving reverses the order:
                out.push(in.pop());                // the oldest item ends up on top of out
                stackOps += 2;
            }
        }
        stackOps++;
        return out.pop();
    }

    public static void main(String[] args) {
        int[] ops = {1, 2, 3, 0, 4, 0, 0, 0};      // a number = push it, 0 = pop
        int pushed = 0;
        for (int x : ops) {
            if (x != 0) { push(x); pushed++; System.out.println("push " + x); }
            else System.out.println("pop -> " + pop());
        }
        System.out.println("Stack operations: " + stackOps + " for " + pushed
            + " elements (at most 4 each = " + (4 * pushed) + ")");
        // Time: O(1) amortized per operation, O(N) worst case for one pop. Space: O(N).
    }
}

