public class Main {
    public static void main(String[] args) {
        int[] a = {1, 3, -1, -3, 5, 3, 6, 7};
        int k = 3, n = a.length;
        int[] dq = new int[n];          // deque of indices kept in a plain array
        int head = 0, tail = 0;         // live part is dq[head .. tail-1]
        String in = "", out = "";
        for (int i = 0; i < n; i++) {
            in += " " + a[i];
            if (head < tail && dq[head] <= i - k) head++;          // front left the window
            // smaller-or-equal values at the back can never be a max again
            while (head < tail && a[dq[tail - 1]] <= a[i]) tail--;
            dq[tail++] = i;
            if (i >= k - 1) out += " " + a[dq[head]];              // front = max of this window
        }
        System.out.println("Input:" + in + ", k = " + k);
        System.out.println("Window maximums:" + out);
        // Time: O(N), each index enters and leaves the deque once. Space: O(k) live entries.
    }
}

