import java.util.*;

public class Main {
    static int prec(char op) { return (op == '+' || op == '-') ? 1 : 2; }

    // pop one operator and two numbers, push the result
    static void apply(Deque<Integer> nums, Deque<Character> ops) {
        char op = ops.pop();
        int b = nums.pop(), a = nums.pop();        // b was pushed last, so it is the right side
        nums.push(op == '+' ? a + b : op == '-' ? a - b : op == '*' ? a * b : a / b);
    }

    static int eval(String s) {
        Deque<Integer> nums = new ArrayDeque<>();
        Deque<Character> ops = new ArrayDeque<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == ' ') continue;
            if (Character.isDigit(c)) {            // read a whole multi-digit number
                int v = 0;
                while (i < s.length() && Character.isDigit(s.charAt(i))) v = v * 10 + (s.charAt(i++) - '0');
                i--;
                nums.push(v);
            } else if (c == '(') {
                ops.push(c);                       // '(' is a wall: nothing below it is applied
            } else if (c == ')') {
                while (ops.peek() != '(') apply(nums, ops);
                ops.pop();
            } else {
                // finish waiting operators that bind at least as tightly (left to right)
                while (!ops.isEmpty() && ops.peek() != '(' && prec(ops.peek()) >= prec(c)) apply(nums, ops);
                ops.push(c);
            }
        }
        while (!ops.isEmpty()) apply(nums, ops);
        return nums.pop();
    }

    public static void main(String[] args) {
        String[] tests = {"3 + 4 * (2 - 1)", "10 / 3 - 2 * (1 + 4)", "(12 + 8) / (7 - 2)"};
        for (String t : tests) System.out.println(t + " = " + eval(t));
        // Time: O(N). Space: O(N) for the two stacks.
    }
}

