            while (i < n && isdigit(s[i])) v = v * 10 + (s[i++] - '0');
            i--;
            nums.push_back(v);
        } else if (c == '(') {
            ops.push_back(c);                  // '(' is a wall: nothing below it is applied
        } else if (c == ')') {
            while (ops.back() != '(') apply(nums, ops);
            ops.pop_back();
        } else {
            // finish waiting operators that bind at least as tightly (left to right)
            while (!ops.empty() && ops.back() != '(' && prec(ops.back()) >= prec(c)) apply(nums, ops);
            ops.push_back(c);
        }
    }
    while (!ops.empty()) apply(nums, ops);
    return nums.back();
}

int main() {
    vector<string> tests = {"3 + 4 * (2 - 1)", "10 / 3 - 2 * (1 + 4)", "(12 + 8) / (7 - 2)"};
    for (const string& t : tests) cout << t << " = " << eval(t) << "\n";
    // Time: O(N). Space: O(N) for the two stacks.
    return 0;
}

