using System;
using System.Collections.Generic;

class Program {
    static int Prec(char op) { return (op == '+' || op == '-') ? 1 : 2; }

    // pop one operator and two numbers, push the result
    static void Apply(Stack<int> nums, Stack<char> ops) {
        char op = ops.Pop();
        int b = nums.Pop(), a = nums.Pop();        // b was pushed last, so it is the right side
        nums.Push(op == '+' ? a + b : op == '-' ? a - b : op == '*' ? a * b : a / b);
    }

    static int Eval(string s) {
        Stack<int> nums = new Stack<int>();
        Stack<char> ops = new Stack<char>();
        for (int i = 0; i < s.Length; i++) {
            char c = s[i];
            if (c == ' ') continue;
            if (char.IsDigit(c)) {                 // read a whole multi-digit number
                int v = 0;
                while (i < s.Length && char.IsDigit(s[i])) v = v * 10 + (s[i++] - '0');
                i--;
                nums.Push(v);
            } else if (c == '(') {
                ops.Push(c);                       // '(' is a wall: nothing below it is applied
            } else if (c == ')') {
                while (ops.Peek() != '(') Apply(nums, ops);
                ops.Pop();
            } else {
                // finish waiting operators that bind at least as tightly (left to right)
                while (ops.Count > 0 && ops.Peek() != '(' && Prec(ops.Peek()) >= Prec(c)) Apply(nums, ops);
                ops.Push(c);
            }
        }
        while (ops.Count > 0) Apply(nums, ops);
        return nums.Pop();
    }

    static void Main() {
        string[] tests = {"3 + 4 * (2 - 1)", "10 / 3 - 2 * (1 + 4)", "(12 + 8) / (7 - 2)"};
        foreach (string t in tests) Console.WriteLine(t + " = " + Eval(t));
        // Time: O(N). Space: O(N) for the two stacks.
    }
}

