import java.util.*;

public class Main {
    public static void main(String[] args) {
        int n = 100000;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i + 1 < n; i++) {          // chain 0 - 1 - 2 - ... - 99999
            adj.get(i).add(i + 1);
            adj.get(i + 1).add(i);
        }

        boolean[] seen = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>(); // lives on the heap, so depth is no problem
        stack.push(0);
        seen[0] = true;
        int visited = 0, last = -1;
        while (!stack.isEmpty()) {
            int u = stack.pop();                   // same job as "enter the recursive call"
            visited++;
            last = u;
            for (int v : adj.get(u)) {
                if (!seen[v]) { seen[v] = true; stack.push(v); }   // mark when pushing: no duplicates
            }
        }
        System.out.println("Nodes in chain: " + n);
        System.out.println("Visited with explicit stack: " + visited);
        System.out.println("Last node reached: " + last);
        // Time: O(V + E). Space: O(V) on the heap instead of one call frame per node.
    }
}

