import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] temp = {73, 74, 75, 71, 69, 72, 76, 73};
        int n = temp.length;
        int[] wait = new int[n];                    // 0 = no warmer day ahead

        // Clue: "for each day, how long until a warmer one" = next greater element.
        // The brute force scans right from every day: O(N^2). The stack does it in O(N).
        Deque<Integer> st = new ArrayDeque<>();     // days still waiting for a warmer day
        for (int i = 0; i < n; i++) {
            while (!st.isEmpty() && temp[st.peek()] < temp[i]) {
                int day = st.pop();
                wait[day] = i - day;                // distance needs indices, not values
            }
            st.push(i);
        }

        String in = "", out = "";
        for (int i = 0; i < n; i++) { in += " " + temp[i]; out += " " + wait[i]; }
        System.out.println("Temperatures:" + in);
        System.out.println("Days until warmer:" + out);
        // Time: O(N). Space: O(N).
    }
}

