import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) throws InterruptedException {
        final int capacity = 3, items = 20, POISON = -1;
        // put() blocks when 3 items are waiting; take() blocks when the queue is empty
        final BlockingQueue<Integer> q = new ArrayBlockingQueue<>(capacity);
        final long[] sum = {0};
        final int[] count = {0};

        Thread producer = new Thread(() -> {
            try {
                for (int i = 1; i <= items; i++) q.put(i);   // waits if the consumer is slow
                q.put(POISON);                               // "no more work" marker
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });

        Thread consumer = new Thread(() -> {
            try {
                while (true) {
                    int x = q.take();                        // waits if nothing is ready
                    if (x == POISON) break;                  // clean shutdown
                    sum[0] += x;
                    count[0]++;
                }
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });

        producer.start();
        consumer.start();
        producer.join();
        consumer.join();
        System.out.println("Capacity " + capacity + ", producer sends 1.." + items);
        System.out.println("Consumer received " + count[0] + " items, sum = " + sum[0]);
        // Time: O(1) per put/take. Space: O(capacity), never more than 3 items in memory.
    }
}

