// JavaScript runs one thread, so "blocking" means awaiting a promise.
class BoundedQueue {
  constructor(capacity) { this.capacity = capacity; this.items = []; this.waiters = []; }
  wakeAll() { const w = this.waiters; this.waiters = []; w.forEach(resume => resume()); }
  async put(x) {
    // full: pause this producer until somebody takes an item
    while (this.items.length === this.capacity) await new Promise(r => this.waiters.push(r));
    this.items.push(x);
    this.wakeAll();
  }
  async take() {
    // empty: pause this consumer until somebody puts an item
    while (this.items.length === 0) await new Promise(r => this.waiters.push(r));
    const x = this.items.shift();
    this.wakeAll();
    return x;
  }
}

const CAPACITY = 3, ITEMS = 20, POISON = -1;
const q = new BoundedQueue(CAPACITY);
let sum = 0, count = 0;

async function producer() {
  for (let i = 1; i <= ITEMS; i++) await q.put(i);   // waits if the consumer is slow
  await q.put(POISON);                               // "no more work" marker
}

async function consumer() {
  while (true) {
    const x = await q.take();                        // waits if nothing is ready
    if (x === POISON) break;                         // clean shutdown
    sum += x;
    count++;
  }
}

Promise.all([producer(), consumer()]).then(() => {
  console.log("Capacity " + CAPACITY + ", producer sends 1.." + ITEMS);
  console.log("Consumer received " + count + " items, sum = " + sum);
});
// Time: O(1) per put/take (shift on 3 items). Space: O(capacity).

