#include <bits/stdc++.h>
using namespace std;

// A tiny version of Java's ArrayBlockingQueue: one lock, one condition variable.
struct BoundedQueue {
    queue<int> q;
    size_t capacity;
    mutex m;
    condition_variable cv;
    explicit BoundedQueue(size_t c) : capacity(c) {}

    void put(int x) {
        unique_lock<mutex> lock(m);
        cv.wait(lock, [&] { return q.size() < capacity; });   // full: sleep until there is room
        q.push(x);
        cv.notify_all();
    }

    int take() {
        unique_lock<mutex> lock(m);
        cv.wait(lock, [&] { return !q.empty(); });            // empty: sleep until an item arrives
        int x = q.front();
        q.pop();
        cv.notify_all();
        return x;
    }
};

int main() {
    const int capacity = 3, items = 20, POISON = -1;
    BoundedQueue bq(capacity);
    long long sum = 0;
    int count = 0;

    thread producer([&] {
        for (int i = 1; i <= items; i++) bq.put(i);   // waits if the consumer is slow
        bq.put(POISON);                               // "no more work" marker
    });
    thread consumer([&] {
        while (true) {
            int x = bq.take();                        // waits if nothing is ready
            if (x == POISON) break;                   // clean shutdown
            sum += x;
            count++;
        }
    });
    producer.join();
    consumer.join();
    cout << "Capacity " << capacity << ", producer sends 1.." << items << "\n";
    cout << "Consumer received " << count << " items, sum = " << sum << "\n";
    // Time: O(1) per put/take. Space: O(capacity), never more than 3 items in memory.
    return 0;
}

