using System;
using System.Collections.Generic;
using System.Threading;

// A tiny version of Java's ArrayBlockingQueue: one lock, wait and wake-up.
class BoundedQueue {
    Queue<int> q = new Queue<int>();
    int capacity;
    object gate = new object();
    public BoundedQueue(int capacity) { this.capacity = capacity; }

    public void Put(int x) {
        lock (gate) {
            while (q.Count == capacity) Monitor.Wait(gate);   // full: sleep until there is room
            q.Enqueue(x);
            Monitor.PulseAll(gate);
        }
    }

    public int Take() {
        lock (gate) {
            while (q.Count == 0) Monitor.Wait(gate);          // empty: sleep until an item arrives
            int x = q.Dequeue();
            Monitor.PulseAll(gate);
            return x;
        }
    }
}

class Program {
    static void Main() {
        int capacity = 3, items = 20, POISON = -1;
        BoundedQueue bq = new BoundedQueue(capacity);
        long sum = 0;
        int count = 0;

        Thread producer = new Thread(() => {
            for (int i = 1; i <= items; i++) bq.Put(i);   // waits if the consumer is slow
            bq.Put(POISON);                               // "no more work" marker
        });
        Thread consumer = new Thread(() => {
            while (true) {
                int x = bq.Take();                        // waits if nothing is ready
                if (x == POISON) break;                   // clean shutdown
                sum += x;
                count++;
            }
        });
        producer.Start();
        consumer.Start();
        producer.Join();
        consumer.Join();
        Console.WriteLine("Capacity " + capacity + ", producer sends 1.." + items);
        Console.WriteLine("Consumer received " + count + " items, sum = " + sum);
        // Time: O(1) per put/take. Space: O(capacity), never more than 3 items in memory.
    }
}

