import java.util.*;

public class Main {
    static int seed = 1;
    static int rnd() { seed = (seed * 75 + 74) % 65537; return seed; }   // tiny repeatable random

    // the solution under review: next strictly greater element, O(N)
    static int[] fast(int[] a) {
        int[] res = new int[a.length];
        Arrays.fill(res, -1);
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < a.length; i++) {
            while (!st.isEmpty() && a[st.peek()] < a[i]) res[st.pop()] = a[i];
            st.push(i);
        }
        return res;
    }

    // the obviously correct version: scan right from every index, O(N^2)
    static int[] brute(int[] a) {
        int[] res = new int[a.length];
        Arrays.fill(res, -1);
        for (int i = 0; i < a.length; i++)
            for (int j = i + 1; j < a.length; j++)
                if (a[j] > a[i]) { res[i] = a[j]; break; }
        return res;
    }

    public static void main(String[] args) {
        int tests = 300, mismatches = 0;
        for (int t = 0; t < tests; t++) {
            int[] a = new int[1 + rnd() % 8];
            for (int i = 0; i < a.length; i++) a[i] = rnd() % 5;   // small values force duplicates
            if (!Arrays.equals(fast(a), brute(a))) mismatches++;
        }
        System.out.println("Arrays: length 1..8, values 0..4 (many duplicates)");
        System.out.println("Random tests run: " + tests);
        System.out.println("Mismatches: " + mismatches);
        // Time: O(tests * N^2) because of the brute force. Space: O(N).
    }
}

