using System;
using System.Collections.Generic;

class Program {
    static int seed = 1;
    static int Rnd() { seed = (seed * 75 + 74) % 65537; return seed; }   // tiny repeatable random

    // the solution under review: next strictly greater element, O(N)
    static int[] Fast(int[] a) {
        int[] res = new int[a.Length];
        for (int i = 0; i < a.Length; i++) res[i] = -1;
        Stack<int> st = new Stack<int>();
        for (int i = 0; i < a.Length; i++) {
            while (st.Count > 0 && a[st.Peek()] < a[i]) res[st.Pop()] = a[i];
            st.Push(i);
        }
        return res;
    }

    // the obviously correct version: scan right from every index, O(N^2)
    static int[] Brute(int[] a) {
        int[] res = new int[a.Length];
        for (int i = 0; i < a.Length; i++) {
            res[i] = -1;
            for (int j = i + 1; j < a.Length; j++)
                if (a[j] > a[i]) { res[i] = a[j]; break; }
        }
        return res;
    }

    static void Main() {
        int tests = 300, mismatches = 0;
        for (int t = 0; t < tests; t++) {
            int[] a = new int[1 + Rnd() % 8];
            for (int i = 0; i < a.Length; i++) a[i] = Rnd() % 5;   // small values force duplicates
            int[] x = Fast(a), y = Brute(a);
            bool same = true;
            for (int i = 0; i < a.Length; i++) if (x[i] != y[i]) same = false;
            if (!same) mismatches++;
        }
        Console.WriteLine("Arrays: length 1..8, values 0..4 (many duplicates)");
        Console.WriteLine("Random tests run: " + tests);
        Console.WriteLine("Mismatches: " + mismatches);
